@prefix she:  <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:ParametersForSoilMonitoring a skos:Concept ;
    skos:prefLabel "parameters for soil monitoring at different sampling intensity levels" ;
    skos:narrower she:SoilErosion,
                  she:SoilCompaction .

she:SamplingIntensityLevel a skos:Concept ;
    skos:prefLabel "sampling intensity level" ;
    skos:narrower she:LevelI,
                  she:LevelII,
                  she:LevelIII .

she:LevelI a skos:Concept ;
    skos:prefLabel "level i" .

she:LevelII a skos:Concept ;
    skos:prefLabel "level ii" .

she:LevelIII a skos:Concept ;
    skos:prefLabel "level iii" .

she:SoilErosion a skos:Concept ;
    skos:prefLabel "soil erosion" ;
    she:seeAlso she:Table7_4 ;
    she:isMonitoredAtLevelI she:ModellingForSoilErosion ;
    she:isMonitoredAtLevelII she:MappingVisibleSoilErosionFeatures,
                             she:DetailsOnLandUseForSoilErosion ;
    she:isMonitoredAtLevelIII she:MonitoringOfSoilErosionSedimentLoads .

she:Table7_4 a skos:Concept ;
    skos:prefLabel "table 7.4" .

she:ModellingForSoilErosion a skos:Concept ;
    skos:prefLabel "modelling (using data on land cover/land use, geomorphological data, national soil data, rainfall)" ;
    she:usesDataOn she:LandCoverLandUseData,
                   she:GeomorphologicalData,
                   she:NationalSoilData,
                   she:RainfallData .

she:LandCoverLandUseData a skos:Concept ;
    skos:prefLabel "land cover/land use data" .

she:GeomorphologicalData a skos:Concept ;
    skos:prefLabel "geomorphological data" .

she:NationalSoilData a skos:Concept ;
    skos:prefLabel "national soil data" .

she:RainfallData a skos:Concept ;
    skos:prefLabel "rainfall data" .

she:MappingVisibleSoilErosionFeatures a skos:Concept ;
    skos:prefLabel "mapping visible soil erosion features" .

she:DetailsOnLandUseForSoilErosion a skos:Concept ;
    skos:prefLabel "details on land use (e.g. ground cover)" .

she:MonitoringOfSoilErosionSedimentLoads a skos:Concept ;
    skos:prefLabel "monitoring (measurements) of soil erosion (sediment loads)" ;
    skos:narrower she:PlotScaleMonitoring,
                  she:CatchmentScaleMonitoring,
                  she:SedimentDepositionMonitoring .

she:PlotScaleMonitoring a skos:Concept ;
    skos:prefLabel "plot scale" .

she:CatchmentScaleMonitoring a skos:Concept ;
    skos:prefLabel "catchment scale" .

she:SedimentDepositionMonitoring a skos:Concept ;
    skos:prefLabel "sediment deposition in ponds, lakes or reservoirs" .

she:SoilCompaction a skos:Concept ;
    skos:prefLabel "soil compaction" ;
    she:seeAlso she:Table8_3 ;
    she:isMonitoredAtLevelI she:PrecompressionStress,
                            she:SoilRigidityRatio,
                            she:PenetrationResistance,
                            she:MorphologicalFeatures,
                            she:SoilOrganicMatterMeasured,
                            she:SaturatedHydraulicConductivity,
                            she:AirCapacity,
                            she:PlantAvailableWaterCapacity,
                            she:SoilTextureCoarseFragmentsCaCO3,
                            she:Rooting ;
    she:isMonitoredAtLevelII she:AllBasicSoilParametersForPTFsMeasured ;
    she:isMonitoredAtLevelIII she:TensiometerSensorsAtRepresentativeSubplots,
                              she:StressDependentMeasurements,
                              she:LevelIIWithGreatSamplingDepthAndMoreSubsamples .

she:Table8_3 a skos:Concept ;
    skos:prefLabel "table 8.3" .

she:PrecompressionStress a skos:Concept ;
    skos:prefLabel "precompression stress (ptf)" ;
    she:involves she:PTF .

she:SoilRigidityRatio a skos:Concept ;
    skos:prefLabel "soil rigidity ratio (ptf)" ;
    she:involves she:PTF .

she:PenetrationResistance a skos:Concept ;
    skos:prefLabel "penetration resistance (ptf)" ;
    she:involves she:PTF .

she:MorphologicalFeatures a skos:Concept ;
    skos:prefLabel "morphological features" .

she:SoilOrganicMatterMeasured a skos:Concept ;
    skos:prefLabel "soil organic matter (measured)" .

she:SaturatedHydraulicConductivity a skos:Concept ;
    skos:prefLabel "saturated hydraulic conductivity" ;
    she:involves she:PTF .

she:AirCapacity a skos:Concept ;
    skos:prefLabel "air capacity" ;
    she:involves she:PTF .

she:PlantAvailableWaterCapacity a skos:Concept ;
    skos:prefLabel "plant available water capacity (ptf)" ;
    she:involves she:PTF .

she:SoilTextureCoarseFragmentsCaCO3 a skos:Concept ;
    skos:prefLabel "soil texture/coarse fragments/caco3 (estimated)" .

she:Rooting a skos:Concept ;
    skos:prefLabel "rooting (estimated)" .

she:AllBasicSoilParametersForPTFsMeasured a skos:Concept ;
    skos:prefLabel "all basic soil parameters for ptfs are measured" ;
    she:involves she:PTF .

she:TensiometerSensorsAtRepresentativeSubplots a skos:Concept ;
    skos:prefLabel "tensiometer, sensors at representative subplots" ;
    she:usesInstrument she:Tensiometer,
                       she:Sensor .

she:Tensiometer a skos:Concept ;
    skos:prefLabel "tensiometer" .

she:Sensor a skos:Concept ;
    skos:prefLabel "sensor" .

she:StressDependentMeasurements a skos:Concept ;
    skos:prefLabel "stress-dependent measurements" .

she:LevelIIWithGreatSamplingDepthAndMoreSubsamples a skos:Concept ;
    skos:prefLabel "as for level ii, but with great sampling depth and more subsamples" ;
    she:isBasedOn she:LevelII ;
    she:hasCharacteristic she:GreatSamplingDepth,
                          she:MoreSubsamples .

she:GreatSamplingDepth a skos:Concept ;
    skos:prefLabel "great sampling depth" .

she:MoreSubsamples a skos:Concept ;
    skos:prefLabel "more subsamples" .

she:GHG a skos:Concept ;
    skos:prefLabel "ghg" ;
    skos:definition "greenhouse gas" .

she:PTF a skos:Concept ;
    skos:prefLabel "ptf" ;
    skos:definition "pedotransfer function" .

@prefix she:  <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:SoilErosionIndicatorsToSupportAgriEnvironmentalPoliciesAtEuropeanAndGlobalLevels a skos:Concept ;
    skos:prefLabel "soil erosion indicators to support agri-environmental policies at european and global levels" ;
    skos:narrower she:AgriEnvironmentalPolicy,
                  she:Indicator .

she:AgriEnvironmentalPolicy a skos:Concept ;
    skos:prefLabel "agri-environmental policy" ;
    skos:narrower she:EUCommonAgriculturalPolicyCAP20142020,
                  she:EUResourceEfficiencyScoreboard,
                  she:EUSustainableDevelopmentGoalsIndicatorSet,
                  she:EUAgriEnvironmentalIndicatorsAEIs .

she:Indicator a skos:Concept ;
    skos:prefLabel "indicator" ;
    skos:narrower she:CAPContextIndicator42SoilErosion,
                  she:EstimatedSoilErosionByWaterAreaAffectedBySevereErosionRate,
                  she:AEI21SoilErosionMeanEstimatedRateOfSoilLossByWaterErosion .

she:EUCommonAgriculturalPolicyCAP20142020 a skos:Concept ;
    skos:prefLabel "eu: common agricultural policy (cap 2014-2020)" ;
    she:usesIndicator she:CAPContextIndicator42SoilErosion .

she:CAPContextIndicator42SoilErosion a skos:Concept ;
    skos:prefLabel "cap context indicator 42: soil erosion" ;
    skos:narrower she:EstimatedRateOfSoilLossByWaterErosion,
                  she:EstimatedAgriculturalAreaAffectedByCertainRateOfSoilErosionByWater .

she:EstimatedRateOfSoilLossByWaterErosion a skos:Concept ;
    skos:prefLabel "sub-indicator: estimated rate of soil loss by water erosion (t/ha/year)" .

she:EstimatedAgriculturalAreaAffectedByCertainRateOfSoilErosionByWater a skos:Concept ;
    skos:prefLabel "estimated agricultural area affected by a certain rate of soil erosion by water (ha)" .

she:EUResourceEfficiencyScoreboard a skos:Concept ;
    skos:prefLabel "eu: resource efficiency scoreboard" ;
    she:usesIndicator she:EstimatedSoilErosionByWaterAreaAffectedBySevereErosionRate .

she:EUSustainableDevelopmentGoalsIndicatorSet a skos:Concept ;
    skos:prefLabel "eu: sustainable development goals indicator set" ;
    she:usesIndicator she:EstimatedSoilErosionByWaterAreaAffectedBySevereErosionRate .

she:EstimatedSoilErosionByWaterAreaAffectedBySevereErosionRate a skos:Concept ;
    skos:prefLabel "estimated soil erosion by water: area affected by severe erosion rate (>10t/ha/year)" .

she:EUAgriEnvironmentalIndicatorsAEIs a skos:Concept ;
    skos:prefLabel "eu: agri-environmental indicators (aeis)" ;
    she:usesIndicator she:AEI21SoilErosionMeanEstimatedRateOfSoilLossByWaterErosion .

she:AEI21SoilErosionMeanEstimatedRateOfSoilLossByWaterErosion a skos:Concept ;
    skos:prefLabel "aei 21: soil erosion: mean estimated rate of soil loss by water erosion (t/ha/year) at various administrative levels (member state, nuts1, nuts2, nuts3)" ;
    she:isMeasuredAt she:MemberState,
                     she:NUTS1,
                     she:NUTS2,
                     she:NUTS3 .

she:NUTS a skos:Concept ;
    skos:prefLabel "nuts" ;
    skos:definition "nomenclature of territorial units for statistics" ;
    skos:narrower she:NUTS1,
                  she:NUTS2,
                  she:NUTS3 .

she:MemberState a skos:Concept ;
    skos:prefLabel "member state" .

she:NUTS1 a skos:Concept ;
    skos:prefLabel "nuts1" .

she:NUTS2 a skos:Concept ;
    skos:prefLabel "nuts2" .

she:NUTS3 a skos:Concept ;
    skos:prefLabel "nuts3" .

@prefix she:  <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:MonitoringBiologicalGroupsResultsFromFrenchSoilMonitoringNetwork a skos:Concept ;
    skos:prefLabel "monitoring biological groups: results from the french soil monitoring network" ;
    skos:narrower she:AbundanceOfEarthwormsNematodesAcariBacterialCommunityMicrobialBiomassEarthwormSpeciesRichness,
                  she:MacroInvertebrateAbundanceCollembolanAbundanceAndRichnessNematodeRichness,
                  she:BiologicalSoilQualityIndexBasedOnSoilMacroInvertebrateCommunityPatterns,
                  she:EarthwormCommunityAndSpecies,
                  she:SoilMicrobialAbundanceAndDiversity .

she:AbundanceOfEarthwormsNematodesAcariBacterialCommunityMicrobialBiomassEarthwormSpeciesRichness a skos:Concept ;
    skos:prefLabel "abundance of earthworms, nematodes, acari and the bacterial community, microbial biomass and earthworm species richness" ;
    she:hasIndicatorValue "main land use (grassland, cropland, forest)" ;
    she:hasSiteDensity "109" ;
    she:hasSource "cluzeau et al. (2012)" .

she:MacroInvertebrateAbundanceCollembolanAbundanceAndRichnessNematodeRichness a skos:Concept ;
    skos:prefLabel "macro-invertebrate abundance, collembolan abundance and richness, and nematode richness" ;
    she:hasIndicatorValue "agricultural practice" .

she:BiologicalSoilQualityIndexBasedOnSoilMacroInvertebrateCommunityPatterns a skos:Concept ;
    skos:prefLabel "biological soil quality index based on soil macro-invertebrate community patterns" ;
    she:hasIndicatorValue "agricultural practice" ;
    she:hasSiteDensity "22" ;
    she:hasSource "ruiz et al. (2011)" .

she:EarthwormCommunityAndSpecies a skos:Concept ;
    skos:prefLabel "earthworm community and species (abundance, biomass, functional structure and ecological traits)" ;
    she:hasIndicatorValue "main land use, degree of soil pollution" ;
    she:hasSiteDensity "13" ;
    she:hasSource "pérès et al. (2011)" .

she:SoilMicrobialAbundanceAndDiversity a skos:Concept ;
    skos:prefLabel "soil microbial abundance and diversity" ;
    she:hasIndicatorValue "main land use and/or agricultural practices" ;
    she:hasSiteDensity ">1700" ;
    she:hasSource "terrat et al. (2017)" .

@prefix she:  <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:OptimalPHValuesForDifferentCrops a skos:Concept ;
    skos:prefLabel "table 4.2 example of optimal ph values for different crops as given in the literature" ;
    skos:narrower she:BeetBeansPeasAndOilseeds,
                  she:CerealsAndMaize,
                  she:Grassland,
                  she:GrasslandHighMolybdenum,
                  she:Potatoes .

she:BeetBeansPeasAndOilseeds a skos:Concept ;
    skos:prefLabel "beet, beans, peas and oilseeds" ;
    she:hasOptimalPH "7.0" .

she:CerealsAndMaize a skos:Concept ;
    skos:prefLabel "cereals and maize" ;
    she:hasOptimalPH "6.5" .

she:Grassland a skos:Concept ;
    skos:prefLabel "grassland" ;
    she:hasOptimalPH "6.3" .

she:GrasslandHighMolybdenum a skos:Concept ;
    skos:prefLabel "grassland (high molybdenum)" ;
    she:hasOptimalPH "<6.2" .

she:Potatoes a skos:Concept ;
    skos:prefLabel "potatoes" ;
    she:hasOptimalPH "6.0" .

@prefix she:  <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:CurrentTargetsAndBaselinesForSoilSealingLandTake a skos:Concept ;
    skos:prefLabel "current targets and baselines for soil sealing/land take in selected european countries" ;
    skos:narrower she:AchieveNoNetLandTakeBy2050,
                  she:DecreaseLandTakeGradually,
                  she:ReduceAnnualLandTakeTo2_5HaDayBy2030AndCompensateUnavoidableSoilSealing,
                  she:ReduceLandTakeForSettlementsAndTrafficRoutesToLessThan30HaDayBy2030,
                  she:ReduceLandConsumptionFrom1_3HaDayTo1HaDayBy2020And0HaDayBy2050,
                  she:HalveLandTakeAtExpenseOfAgriculturalLandUntil2020AndReduceUrbanSprawl,
                  she:StopNetLandSoilTakeUseBy2050 .

# Column Headers as Concepts
she:TargetColumn a skos:Concept ;
    skos:prefLabel "target" .

she:IndicatorColumn a skos:Concept ;
    skos:prefLabel "indicator" .

she:SourceColumn a skos:Concept ;
    skos:prefLabel "source" .

# Target Concepts and their relationships
she:AchieveNoNetLandTakeBy2050 a skos:Concept ;
    skos:prefLabel "achieve no net land take by 2050" ;
    she:hasIndicator she:LandTakeKm2Per3YearPeriod ;
    she:hasSource she:EURoadmapToAResourceEfficientEurope .

she:DecreaseLandTakeGradually a skos:Concept ;
    skos:prefLabel "to decrease land take gradually: 2016: land take 6ha/day (baseline) 2025 interim target 3ha/day 2040 final target 0ha/day ('land take neutral')" ;
    she:hasIndicator she:AverageAnnualLandTakeMeasuredInHectaresPerDay ;
    she:hasSource she:FlandersStrategicVisionOfSpatialPolicyPlanOfFlanders .

she:ReduceAnnualLandTakeTo2_5HaDayBy2030AndCompensateUnavoidableSoilSealing a skos:Concept ;
    skos:prefLabel "to reduce annual land take to a rate of 2.5ha/day by 2030 and to compensate unavoidable soil sealing" ;
    she:hasIndicator she:AverageAnnualLandTakeMeasuredInHectaresPerDay ;
    she:hasSource she:AustrianGovernmentProgramme20202024 .

she:ReduceLandTakeForSettlementsAndTrafficRoutesToLessThan30HaDayBy2030 a skos:Concept ;
    skos:prefLabel "to reduce land take for settlements and traffic routes to less than 30ha/day by 2030 (at present 52ha/day as a 4-year average from 2016 to 2019)" ;
    she:hasIndicator she:AverageAnnualLandTakeMeasuredInHectaresPerDay ;
    she:hasSource she:GermanSustainabilityStrategy2016 .

she:ReduceLandConsumptionFrom1_3HaDayTo1HaDayBy2020And0HaDayBy2050 a skos:Concep

@prefix she:  <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:FactorsContributingToDifferencesInRiskAssessmentToolsAndApproachesAndToDifferencesInSSVsAmongEUMemberStates a skos:Concept ;
    skos:prefLabel "factors contributing to differences in risk assessment tools and approaches, and to differences in ssvs among eu member states" ;
    skos:narrower she:ConditioningFactor,
                  she:RoleInRiskAssessment .

she:ConditioningFactor a skos:Concept ;
    skos:prefLabel "conditioning factor" ;
    skos:narrower she:GeographicalFactors,
                  she:ClimaticFactors,
                  she:CulturalFactors,
                  she:RegulatoryAndPoliticalFactors,
                  she:ScientificFactors .

she:RoleInRiskAssessment a skos:Concept ;
    skos:prefLabel "role in risk assessment" .

she:GeographicalFactors a skos:Concept ;
    skos:prefLabel "geographical factors" ;
    skos:narrower she:SoilProperties,
                  she:DepthOfGroundwaterTable .

she:SoilProperties a skos:Concept ;
    skos:prefLabel "soil properties" ;
    she:hasRoleInRiskAssessment "(bio)availability affecting ecology as well as filtering function" .

she:DepthOfGroundwaterTable a skos:Concept ;
    skos:prefLabel "depth of groundwater table" ;
    she:hasRoleInRiskAssessment "vapour intrusion and, hence, human exposure through inhalation. it also affects the potential impact of soil quality on water quality, since contact time between soil and surface water is shorter in areas with high water tables" .

she:ClimaticFactors a skos:Concept ;
    skos:prefLabel "climatic factors" ;
    skos:narrower she:TimeSpentOutdoors,
                  she:NetAnnualWaterSurplus,
                  she:TemperatureRainfall .

she:TimeSpentOutdoors a skos:Concept ;
    skos:prefLabel "time spent outdoors" ;
    she:hasRoleInRiskAssessment "potential contact with soil and, hence, exposure through soil ingestion" .

she:NetAnnualWaterSurplus a skos:Concept ;
    skos:prefLabel "net annual water surplus" ;
    she:hasRoleInRiskAssessment "leaching/accumulation is controlled largely by water flux (in combination with soil properties)" .

she:TemperatureRainfall a skos:Concept ;
    skos:prefLabel "temperature/rainfall" ;
    she:hasRoleInRiskAssessment "climate controls crop types used by farmers and hence potential uptake of pollutants from soil" .

she:CulturalFactors a skos:Concept ;
    skos:prefLabel "cultural factors" ;
    skos:narrower she:SelfSupplyGardeningSubsistenceFarming,
                  she:UrbanRecreation,
                  she:DrinkingWaterFromPrivateWells .

she:SelfSupplyGardeningSubsistenceFarming a skos:Concept ;
    skos:prefLabel "self-supply gardening, subsistence farming" ;
    she:hasRoleInRiskAssessment "exposure through the consumption of vegetables grown in kitchen gardens" .

she:UrbanRecreation a skos:Concept ;
    skos:prefLabel "urban recreation" .

she:DrinkingWaterFromPrivateWells a skos:Concept ;
    skos:prefLabel "drinking water from private wells" ;
    she:hasRoleInRiskAssessment "exposure through the consumption of groundwater as drinking water" .

she:RegulatoryAndPoliticalFactors a skos:Concept ;
    skos:prefLabel "regulatory and political factors" ;
    skos:narrower she:PrioritisationOfEconomicAndEnvironmentalValues,
                  she:ComplementaritiesWithOtherExistingLaws,
                  she:Governance .

she:PrioritisationOfEconomicAndEnvironmentalValues a skos:Concept ;
    skos:prefLabel "prioritisation of economic and environmental values" ;
    she:hasRoleInRiskAssessment "role and use of background values" .

she:ComplementaritiesWithOtherExistingLaws a skos:Concept ;
    skos:prefLabel "complementarities with other existing laws" ;
    she:hasRoleInRiskAssessment "definition of attributes in risk assessment" .

she:Governance a skos:Concept ;
    skos:prefLabel "governance" ;
    she:hasRoleInRiskAssessment "authorities involved and responsible\nland reclamation policies, spatial planning, drinking water protection" .

she:ScientificFactors a skos:Concept ;
    skos:prefLabel "scientific factors" ;
    skos:narrower she:ScientificAndAnalyticalExperienceAndCooperation,
                  she:FundingRegime .

she:ScientificAndAnalyticalExperienceAndCooperation a skos:Concept ;
    skos:prefLabel "scientific and analytical experience and cooperation" ;
    she:hasRoleInRiskAssessment "selection of protection targets and exposure pathways\nmethod and use of background concentrations\ntoxicological data sources" .

she:FundingRegime a skos:Concept ;
    skos:prefLabel "funding regime" ;
    she:hasRoleInRiskAssessment "acceptable exposure, exposure time, aggregate exposure\nmixtures and non-soil sources" .

@prefix she:  <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

she:RelationshipOfSoilCompactionToSocietalNeedsAndSoilFunctions a skos:Concept ;
    skos:prefLabel "relationship of soil compaction to key societal needs and soil functions" ;
    skos:narrower she:SocietalNeed,
                  she:SoilService,
                  she:Impact .

she:SocietalNeed a skos:Concept ;
    skos:prefLabel "societal need" ;
    skos:narrower she:Biomass,
                  she:Water,
                  she:Air,
                  she:Climate,
                  she:Biodiversity,
                  she:CulturalHeritage,
                  she:Infrastructure .

she:SoilService a skos:Concept ;
    skos:prefLabel "soil service" ;
    skos:narrower she:WoodAndFibreProduction,
                  she:GrowthAndQualityOfCrops,
                  she:FilteringAndBufferingOfContaminantsIncludingSupplyOfDrinkingWater,
                  she:WaterStorageAndAvailabilityGroundwaterRechargeSurfaceRunOffAndInterflow,
                  she:CompositionAndExchangeOfSoilGasWithTheAtmosphere,
                  she:CarbonStorageAndTurnoverAvoidanceOfGreenhouseGasReleases,
                  she:HabitatForPlantsInsectsMicrobesFungi,
                  she:DocumentationOfHistoricalHumanCultureAndLandManagement,
                  she:PlatformForInfrastructure,
                  she:StorageOfGeologicalMaterial .

she:Impact a skos:Concept ;
    skos:prefLabel "impact" ;
    skos:narrower she:NegativeImpact,
                  she:IndifferentImpact .

she:SoilCompaction a skos:Concept ;
    skos:prefLabel "soil compaction" .

she:Biomass a skos:Concept ;
    skos:prefLabel "biomass" .

she:Water a skos:Concept ;
    skos:prefLabel "water" .

she:Air a skos:Concept ;
    skos:prefLabel "air" .

she:Climate a skos:Concept ;
    skos:prefLabel "climate" .

she:Biodiversity a skos:Concept ;
    skos:prefLabel "biodiversity" .

she:CulturalHeritage a skos:Concept ;
    skos:prefLabel "cultural heritage" .

she:Infrastructure a skos:Concept ;
    skos:prefLabel "infrastructure" .

she:NegativeImpact a skos:Concept ;
    skos:prefLabel "negative impact" ;
    skos:definition "a detrimental impact from soil compaction" .

she:IndifferentImpact a skos:Concept ;
    skos:prefLabel "indifferent impact" ;
    skos:definition "no significant impact from soil compaction" .

she:WoodAndFibreProduction a skos:Concept ;
    skos:prefLabel "wood and fibre production" ;
    she:servesSocietalNeed she:Biomass ;
    she:isAffectedBySoilCompactionWithImpact she:NegativeImpact .

she:GrowthAndQualityOfCrops a skos:Concept ;
    skos:prefLabel "growth and quality of crops" ;
    she:servesSocietalNeed she:Biomass ;
    she:isAffectedBySoilCompactionWithImpact she:NegativeImpact .

she:FilteringAndBufferingOfContaminantsIncludingSupplyOfDrinkingWater a skos:Concept ;
    skos:prefLabel "filtering and buffering of contaminants, including supply of drinking water" ;
    she:servesSocietalNeed she:Water ;
    she:isAffectedBySoilCompactionWithImpact she:NegativeImpact .

she:WaterStorageAndAvailabilityGroundwaterRechargeSurfaceRunOffAndInterflow a skos:Concept ;
    skos:prefLabel "water storage and availability, groundwater recharge, surface run-off and interflow" ;
    she:servesSocietalNeed she:Water ;
    she:isAffectedBySoilCompactionWithImpact she:NegativeImpact .

she:CompositionAndExchangeOfSoilGasWithTheAtmosphere a skos:Concept ;
    skos:prefLabel "composition and exchange of soil gas with the atmosphere" ;
    she:servesSocietalNeed she:Air ;
    she:isAffectedBySoilCompactionWithImpact she:NegativeImpact .

she:CarbonStorageAndTurnoverAvoidanceOfGreenhouseGasReleases a skos:Concept ;
    skos:prefLabel "carbon storage and turnover, avoidance of greenhouse gas releases (e.g. nitrous oxide, methane)" ;
    she:servesSocietalNeed she:Climate ;
    she:isAffectedBySoilCompactionWithImpact she:NegativeImpact .

she:HabitatForPlantsInsectsMicrobesFungi a skos:Concept ;
    skos:prefLabel "habitat for plants, insects, microbes, fungi" ;
    she:servesSocietalNeed she:Biodiversity ;
    she:isAffectedBySoilCompactionWithImpact she:NegativeImpact .

she:DocumentationOfHistoricalHumanCultureAndLandManagement a skos:Concept ;
    skos:prefLabel "documentation of historical human culture and land management" ;
    she:servesSocietalNeed she:CulturalHeritage ;
    she:isAffectedBySoilCompactionWithImpact she:NegativeImpact .

she:PlatformForInfrastructure a skos:Concept ;
    skos:prefLabel "platform for infrastructure" ;
    she:servesSocietalNeed she:Infrastructure ;
    she:isAffectedBySoilCompactionWithImpact she:IndifferentImpact .

she:StorageOfGeologicalMaterial a skos:Concept ;
    skos:prefLabel "storage of geological material" ;
    she:servesSocietalNeed she:Infrastructure ;
    she:isAffectedBySoilCompactionWithImpact she:IndifferentImpact .

