she:MainCharacteristicsOfDiffuseAndPointSourceSoilPollution a skos:Concept ;
    skos:prefLabel "main characteristics of diffuse and point source soil pollution" ;
    skos:narrower she:DiffusePollution,
                  she:PointSourcePollution .

she:DiffusePollution a skos:Concept ;
    skos:prefLabel "diffuse pollution" ;
    she:hasCharacteristic she:DiffusePollutionSource,
                          she:DiffusePollutionProtectionTarget,
                          she:DiffusePollutionProceduralFramework,
                          she:DiffusePollutionAvailabilityThresholdsInReceptors,
                          she:DiffusePollutionPolicy .

she:PointSourcePollution a skos:Concept ;
    skos:prefLabel "point source pollution" ;
    she:hasCharacteristic she:PointSourcePollutionSource,
                          she:PointSourcePollutionProtectionTarget,
                          she:PointSourcePollutionProceduralFramework,
                          she:PointSourcePollutionAvailabilityThresholdsInReceptors,
                          she:PointSourcePollutionPolicy .

she:Source a skos:Concept ;
    skos:prefLabel "source" ;
    skos:narrower she:DiffusePollutionSource,
                  she:PointSourcePollutionSource .

she:DiffusePollutionSource a skos:Concept ;
    skos:prefLabel "diffuse pollution source" ;
    skos:definition "largely ongoing in agricultural areas due to application of plant protection products and nutrients resulting in emission of metals, microplastics and/or nanoparticles. partially historical in the case of floodplain soils or cases of proximity pollution. immobile and persistent organic chemicals used in the past can still be found in specific forms of land use (e.g. ddt in areas with intensive fruit tree cropping)." .

she:PointSourcePollutionSource a skos:Concept ;
    skos:prefLabel "point source pollution source" ;
    skos:definition "largely historical resulting from (historical) industrial emissions. current emissions on land from large industrial installations (ied) are hardly reported (vs emission to air and water), but it is likely that the percentage of areas affected by ongoing point source pollution varies depending on the degree of implementation of existing legislation in individual member states and required legal obligations to reduce emissions and/or remediate polluted sites." .

she:ProtectionTarget a skos:Concept ;
    skos:prefLabel "protection target" ;
    skos:narrower she:DiffusePollutionProtectionTarget,
                  she:PointSourcePollutionProtectionTarget .

she:DiffusePollutionProtectionTarget a skos:Concept ;
    skos:prefLabel "diffuse pollution protection target" ;
    skos:definition "mostly targeting arable cropping systems, including animal husbandry (grassland); more recently, adjacent terrestrial and aquatic ecosystems are also considered. direct human exposure is considered in the case of proximity pollution." .

she:PointSourcePollutionProtectionTarget a skos:Concept ;
    skos:prefLabel "point source pollution protection target" ;
    skos:definition "primarily focused on human health and on the soil ecosystem directly located at or near the polluted area. in addition, drinking water resources that are affected by leaching from soil or direct emissions into the water body are considered." .

she:ProceduralFramework a skos:Concept ;
    skos:prefLabel "procedural framework" ;
    skos:narrower she:DiffusePollutionProceduralFramework,
                  she:PointSourcePollutionProceduralFramework .

she:DiffusePollutionProceduralFramework a skos:Concept ;
    skos:prefLabel "diffuse pollution procedural framework" ;
    skos:definition "soil screening values and/or relevant risk limits in products are based on (1) at source level, i.e. quantity and quality of applied substances (sludges, fertiliser quality), (2) at effect level, i.e. risk limits for foodstuffs and drinking water quality. in many countries natural background levels are used as a first screening level even though these are not necessarily related to the risks of pollutants as such." .

she:PointSourcePollutionProceduralFramework a skos:Concept ;
    skos:prefLabel "point source pollution procedural framework" ;
    skos:definition "tiered approaches for risk-based assessment, usually combining thresholds for soil and groundwater based on human health risks (exposure) and toxic effects on the ecosystem (ecotoxicological response of selected species). risk assessment aims to ensure that the future intended land use remains below agreed risk levels." .

she:AvailabilityThresholdsInReceptors a skos:Concept ;
    skos:prefLabel "availability thresholds in receptors" ;
    skos:narrower she:DiffusePollutionAvailabilityThresholdsInReceptors,
                  she:PointSourcePollutionAvailabilityThresholdsInReceptors .

she:DiffusePollutionAvailabilityThresholdsInReceptors a skos:Concept ;
    skos:prefLabel "diffuse pollution availability thresholds in receptors" ;
    skos:definition "largely confined to nutrients (in surface water and groundwater), selected metals/metalloids (in plant products) and an array of plant protection chemicals used in agriculture. the number of other organic chemicals included in assessments of diffuse pollution varies strongly per country." .

she:PointSourcePollutionAvailabilityThresholdsInReceptors a skos:Concept ;
    skos:prefLabel "point source pollution availability thresholds in receptors" ;
    skos:definition "for most metals/metalloids, pahs, aromatic compounds (including btex), volatile organic chlorinated compounds, mineral oil, asbestos and other commonly observed organic chemicals produced and emitted by industry; thresholds are available for human health based on exposure (tdi) and reference dose or soil organisms (ecological effects levels)." .

she:Policy a skos:Concept ;
